/* Build site/js/vsop87.js from the astronomia package's full VSOP87B
 * data (MIT licensed; VSOP87 itself is from the Bureau des Longitudes).
 * Truncates each series to terms whose amplitude can still move the
 * result by more than about half an arcsecond, which keeps the file
 * small while leaving the accuracy effectively at full-series level.
 *
 * Prerequisites: npm install astronomia (in a scratch dir), then
 *   ASTRONOMIA=/path/to/node_modules/astronomia node tools/build-vsop87.js
 * The generated file is committed to the site; this script is not
 * needed at runtime.
 */
"use strict";
const fs = require("fs");
const path = require("path");
const { pathToFileURL } = require("url");

const SRC = process.env.ASTRONOMIA || "/tmp/npmtest/node_modules/astronomia";
const PLANETS = ["earth", "mercury", "venus", "mars", "jupiter", "saturn", "uranus", "neptune"];
const KEEP = { L: 2.5e-6, B: 2.5e-6, R: 2.5e-5 }; // radians / AU

function round(x, digits) {
  if (x === 0) return 0;
  const p = Math.pow(10, digits - 1 - Math.floor(Math.log10(Math.abs(x))));
  return Math.round(x * p) / p;
}

(async () => {
  const out = {};
  let termsIn = 0, termsOut = 0;
  for (const name of PLANETS) {
    const mod = await import(pathToFileURL(path.join(SRC, "data", "vsop87B" + name + ".js")).href);
    const data = mod.default;
    out[name] = {};
    for (const coord of ["L", "B", "R"]) {
      out[name][coord] = [];
      const powers = Object.keys(data[coord]).sort();
      for (const pw of powers) {
        const kept = data[coord][pw]
          .filter((t) => Math.abs(t[0]) >= KEEP[coord])
          .map((t) => [round(t[0], 7), round(t[1], 7), round(t[2], 7)]);
        termsIn += data[coord][pw].length;
        termsOut += kept.length;
        out[name][coord].push(kept);
      }
    }
  }
  const banner = "/* VSOP87B planetary series, truncated (terms below ~0.5 arcsec dropped).\n" +
    " * Data: VSOP87 (Bureau des Longitudes) via the astronomia package (MIT).\n" +
    " * Generated by tools/build-vsop87.js; do not edit by hand. */\n";
  fs.writeFileSync(__dirname + "/../js/vsop87.js",
    banner + "const VSOP87 = " + JSON.stringify(out) + ";\n" +
    "if (typeof module !== \"undefined\") module.exports = VSOP87;\n" +
    "if (typeof window !== \"undefined\") window.VSOP87 = VSOP87;\n");
  const bytes = fs.statSync(__dirname + "/../js/vsop87.js").size;
  console.log("terms kept " + termsOut + " of " + termsIn + "; file " + (bytes / 1024).toFixed(0) + " KB");
})();
